@Override
    public OrderE getOrder(String orderNo, String checkCode) {
        OrderDO orderDO = orderMapper.selectByPrimaryKey(orderNo, checkCode);
        if (orderDO == null) {
            ExceptionUtils.throwFailureException(ErrorEnum.SYS_INNER_DB_NOT_EXIST, "订单不存在" + orderNo);
        }

        OrderE orderE = OrderConverter.convertDomain(orderDO);
        List<OrderNodeDO> list = orderNodeMapper.listNodeByOrderNo(orderNo);
        if (list != null && !list.isEmpty()) {
            List<NodeE> nodeEList = new ArrayList<>(list.size());
            for (OrderNodeDO orderNodeDO : list) {
                nodeEList.add(NodeConverter.convertProject(orderE, orderNodeDO));
            }
            orderE.setNodeEList(nodeEList);
        }
        return orderE;
    }

public void batchExecute(String beforeDate) {
        List<ClaimOrderE> claimOrderEList = claimOrderFactory.queryInitClaimOrders(beforeDate);
        //设置为失效状态
        claimOrderEList.stream().filter(claimOrderE -> !claimOrderE.getStatus().equals(StatusV.SUCCESS)).forEach(claimOrderE -> {
            OrderE orderE = null;
            try {
                orderE = orderRepository.getOrder(claimOrderE.getOrderNo(), null);
            } catch (Exception e) {
                LOGGER.warn("getOrder error orderNo : {}", claimOrderE.getOrderNo());
            }
            if (orderE != null) {
                orderE.setIsValid(0);
                orderRepository.updateOrder(orderE);

                claimOrderE.setIsValid(0);
                claimOrderE.updateClaimOrder(claimOrderE);
            }
        });
    }

@Override
    public void updateOrder(OrderE order) {
        int count = orderMapper.updateByPrimaryKeySelective(OrderConverter.convertEntity(order));
        if (count == 0) {
            ExceptionUtils.throwFailureException(ErrorEnum.SYS_INNER_DB_UPDATE_ERROR, "更新数量为0");
        }
    }

public static OrderDO convertEntity(OrderE orderE) {
        OrderDO orderDO = new OrderDO();
        orderDO.setOrderNo(orderE.getOrderNo());
        orderDO.setOrderType(orderE.getOrderType().name());
        orderDO.setAppCode(orderE.getAppCode());
        orderDO.setFinishTime(orderE.getFinishTime());
        orderDO.setStatus(orderE.getStatus().getCode());
        orderDO.setBizCode(orderE.getBizCode());
        orderDO.setCheckCode(orderE.getCheckCode());
        orderDO.setBizData(CommonConverter.getDataToString(orderE.getBizData()));
        orderDO.setResultData(CommonConverter.getDataToString(orderE.getResultData()));
//        orderDO.setEventName();
        orderDO.setUserId(orderE.getUserId());
        orderDO.setIsValid(orderE.getIsValid());
        orderDO.setGmtModified(new Date());
        orderDO.setUpdateCheckValue(CommonConverter.getUpdateCheckValue(orderE.getOldV()));
        //todo hash对比，hash一致不进行赋值（更新）
        return orderDO;
    }

public static void throwFailureException(Throwable e, ErrorEnum errorEnum, Object... args) {
        throw createFailureException(e, errorEnum, args);
    }

public List<ClaimOrderE> queryInitClaimOrders(String beforeDate) {
        List<ClaimOrderE> claimOrderEList = claimOrderGateway.queryInitClaimOrders(beforeDate);
        claimOrderEList.forEach(claimOrderE -> claimOrderE.setClaimOrderGateway(claimOrderGateway));
        return claimOrderEList;
    }

public static String getNodeNo(String orderNo, String nodeType, String currentTime) {
        return UUID.nameUUIDFromBytes(
            new StringBuilder().append(orderNo).append(nodeType).append(currentTime).toString()
                .getBytes()).toString().replace("-", "");
    }
